//! Evidence shown beside the branch diff in review mode, read from the files
//! that `project_map.py`, `project_history.py` and `review_checks.py` write
//! to `.rubiks/`. Facts only: nothing here is generated by a model.

use std::{collections::HashMap, path::Path};

use gpui::{App, IntoElement, ParentElement, Styled, px};
use ui::prelude::*;

const MAP_FILE: &str = ".rubiks/map.md";
const HISTORY_FILE: &str = ".rubiks/architecture.md";
const READINESS_FILE: &str = ".rubiks/readiness.md";
const MAP_COLUMNS: [&str; 8] = [
    "Path",
    "Area",
    "Language",
    "Lines",
    "Purpose",
    "Main symbols",
    "Tests",
    "Last change",
];

#[derive(Debug, Default, PartialEq)]
pub(crate) struct ReviewEvidence {
    files: HashMap<String, Vec<String>>,
    hotspots: HashMap<String, Vec<String>>,
    readiness_scope: Option<String>,
    checks: Vec<(String, String)>,
    missing: Vec<&'static str>,
}

impl ReviewEvidence {
    /// Returns `None` when the repository has no `.rubiks` directory, so review
    /// evidence stays out of the way in projects that don't use it.
    pub(crate) fn load(work_directory: &Path) -> Option<Self> {
        if !work_directory.join(".rubiks").is_dir() {
            return None;
        }
        let read = |name: &str| std::fs::read_to_string(work_directory.join(name)).ok();
        Some(Self::from_texts(
            read(MAP_FILE),
            read(HISTORY_FILE),
            read(READINESS_FILE),
        ))
    }

    fn from_texts(map: Option<String>, history: Option<String>, readiness: Option<String>) -> Self {
        let mut evidence = Self::default();
        let keyed = |rows: Vec<Vec<String>>| -> HashMap<String, Vec<String>> {
            rows.into_iter()
                .filter_map(|mut row| (!row.is_empty()).then(|| (row.remove(0), row)))
                .collect()
        };
        match map {
            Some(text) => evidence.files = keyed(table_rows(&text, "Path | Area")),
            None => evidence.missing.push("python3 scripts/project_map.py"),
        }
        match history {
            Some(text) => evidence.hotspots = keyed(table_rows(&text, "Area | Commits")),
            None => evidence.missing.push("python3 scripts/project_history.py"),
        }
        match readiness {
            Some(text) => {
                evidence.readiness_scope = text
                    .lines()
                    .find(|line| line.starts_with("Branch against"))
                    .map(str::to_string);
                evidence.checks = table_rows(&text, "Check | Command")
                    .into_iter()
                    .filter_map(|row| Some((row.first()?.clone(), row.get(2)?.clone())))
                    .collect();
            }
            None => evidence.missing.push("python3 scripts/review_checks.py"),
        }
        evidence
    }

    pub(crate) fn render(&self, path: Option<&str>, cx: &App) -> impl IntoElement {
        let colors = cx.theme().colors();
        let file = path.and_then(|path| self.files.get(path));
        let area = file.and_then(|row| row.first());
        let hotspot = area.and_then(|area| self.hotspots.get(area));

        let heading = |text: &'static str| {
            Label::new(text)
                .size(LabelSize::Small)
                .color(Color::Muted)
                .weight(gpui::FontWeight::SEMIBOLD)
        };
        let fact = |name: &str, value: &str| {
            v_flex()
                .gap_0p5()
                .child(
                    Label::new(name.to_string())
                        .size(LabelSize::XSmall)
                        .color(Color::Muted),
                )
                .child(
                    Label::new(if value.is_empty() {
                        "—".to_string()
                    } else {
                        value.to_string()
                    })
                    .size(LabelSize::Small),
                )
        };

        let file_section = match (path, file) {
            (_, Some(row)) => v_flex().gap_2().children(
                MAP_COLUMNS
                    .iter()
                    .skip(1)
                    .zip(row.iter())
                    .map(|(name, value)| fact(name, value)),
            ),
            (Some(path), None) => v_flex().child(
                Label::new(format!(
                    "{path} isn't in the project table. Regenerate it if the file is new."
                ))
                .size(LabelSize::Small)
                .color(Color::Muted),
            ),
            (None, None) => v_flex().child(
                Label::new("Move the cursor into a file to see its evidence.")
                    .size(LabelSize::Small)
                    .color(Color::Muted),
            ),
        };

        let history_section = match (area, hotspot) {
            (Some(area), Some(row)) => v_flex().gap_2().child(fact("Area", area)).children(
                ["Commits", "Lines changed", "Last change"]
                    .iter()
                    .zip(row.iter())
                    .map(|(name, value)| fact(name, value)),
            ),
            _ => v_flex().child(
                Label::new("No history for this area in the period covered.")
                    .size(LabelSize::Small)
                    .color(Color::Muted),
            ),
        };

        let readiness_section = v_flex()
            .gap_1()
            .when_some(self.readiness_scope.clone(), |this, scope| {
                this.child(
                    Label::new(scope)
                        .size(LabelSize::XSmall)
                        .color(Color::Muted),
                )
            })
            .when(self.checks.is_empty(), |this| {
                this.child(
                    Label::new("No check results yet.")
                        .size(LabelSize::Small)
                        .color(Color::Muted),
                )
            })
            .children(self.checks.iter().map(|(name, result)| {
                let color = if result == "pass" {
                    Color::Success
                } else if result.starts_with("fails only") {
                    Color::Warning
                } else {
                    Color::Error
                };
                h_flex()
                    .gap_2()
                    .justify_between()
                    .child(Label::new(name.clone()).size(LabelSize::Small))
                    .child(
                        Label::new(result.clone())
                            .size(LabelSize::XSmall)
                            .color(color),
                    )
            }));

        v_flex()
            .id("review-evidence")
            .w(px(300.))
            .h_full()
            .flex_none()
            .overflow_y_scroll()
            .p_3()
            .gap_4()
            .border_l_1()
            .border_color(colors.border)
            .bg(colors.panel_background)
            .child(heading("THIS FILE"))
            .child(file_section)
            .child(heading("AREA HISTORY"))
            .child(history_section)
            .child(heading("READINESS"))
            .child(readiness_section)
            .when(!self.missing.is_empty(), |this| {
                this.child(heading("NOT GENERATED"))
                    .children(self.missing.iter().map(|command| {
                        Label::new(command.to_string())
                            .size(LabelSize::XSmall)
                            .color(Color::Muted)
                    }))
            })
    }
}

/// Rows of the first markdown table whose header starts with `header_start`
/// (cells joined by " | "), with escaped pipes restored and the header and
/// divider dropped.
fn table_rows(text: &str, header_start: &str) -> Vec<Vec<String>> {
    let header = format!("| {header_start} |");
    let Some(start) = text.lines().position(|line| line.starts_with(&header)) else {
        return Vec::new();
    };
    text.lines()
        .skip(start + 2)
        .take_while(|line| line.starts_with('|'))
        .map(|line| {
            line.trim()
                .trim_matches('|')
                .replace("\\|", "\u{0}")
                .split('|')
                .map(|cell| cell.trim().replace('\u{0}', "|"))
                .collect()
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_rows_reads_the_named_table_and_restores_escaped_pipes() {
        let text = "# Map\n\n| Other | x |\n|---|---|\n| no | 1 |\n\n| Path | Area |\n|---|---|\n| src/a.rs | a \\| b |\n| src/b.rs | c |\n\nAfter.\n";
        assert_eq!(
            table_rows(text, "Path"),
            vec![
                vec!["src/a.rs".to_string(), "a | b".to_string()],
                vec!["src/b.rs".to_string(), "c".to_string()],
            ]
        );
        assert!(table_rows(text, "Missing").is_empty());
    }

    #[test]
    fn from_texts_keys_rows_and_reports_missing_files() {
        let map = "| Path | Area | Language | Lines | Purpose | Main symbols | Tests | Last change |\n|---|---|---|---|---|---|---|---|\n| src/a.rs | src | Rust | 10 | Does a | A | inline | abc 2026-11-09 |\n";
        let history = "| Area | Added | Removed |\n|---|---|---|\n| src | x | |\n\n| Area | Commits | Lines changed | Last change |\n|---|---|---|---|\n| src | 3 | 40 | abc 2026-11-09 |\n";
        let evidence = ReviewEvidence::from_texts(Some(map.into()), Some(history.into()), None);
        assert_eq!(
            evidence.files.get("src/a.rs"),
            Some(&vec![
                "src".to_string(),
                "Rust".to_string(),
                "10".to_string(),
                "Does a".to_string(),
                "A".to_string(),
                "inline".to_string(),
                "abc 2026-11-09".to_string(),
            ])
        );
        assert_eq!(
            evidence.hotspots.get("src"),
            Some(&vec![
                "3".to_string(),
                "40".to_string(),
                "abc 2026-11-09".to_string()
            ])
        );
        assert_eq!(evidence.missing, vec!["python3 scripts/review_checks.py"]);
    }
}
